/* ══════════════════════════════════════════════════════════════
   👋 FIRST-RUN ONBOARDING (name / gender / avatar)
   ══════════════════════════════════════════════════════════════ */
const LOCAL_AVATARS = {"M1": "data:image/png;base64,", "M2": "data:image/png;base64,", "M3": "data:image/png;base64,", "M4": "data:image/png;base64,", "F1": "data:image/png;base64,", "F2": "data:image/png;base64,", "F3": "data:image/png;base64,", "F4": "data:image/png;base64,"};
const AVATAR_KEYS = { male: ['M1','M2','M3','M4'], female: ['F1','F2','F3','F4'] };
function dicebearUrl(key) { return LOCAL_AVATARS[key]; }
let onboardGender = 'male';
function getUserProfile() {
  return JSON.parse(localStorage.getItem('drmonic_user_profile') || 'null');
}
function initOnboarding() {
  if (getUserProfile()) { applyPersonalization(); return; }
  onboardSetGender('male');
  document.getElementById('onboardModal').classList.add('open');
}
function onboardSetGender(g) {
  onboardGender = g;
  document.getElementById('onboardMaleBtn').classList.toggle('btn-primary', g === 'male');
  document.getElementById('onboardFemaleBtn').classList.toggle('btn-primary', g === 'female');
  const row = document.getElementById('onboardEmojiRow');
  row.innerHTML = AVATAR_KEYS[g].map((key, i) => `
    <button type="button" class="avatar-opt${i===0?' selected':''}" data-avatar-url="${dicebearUrl(key)}" onclick="onboardPickAvatar(this)">
      <img src="${dicebearUrl(key)}" alt="avatar" width="96" height="96" />
    </button>`).join('');
}
function onboardPickAvatar(btn) {
  btn.parentElement.querySelectorAll('.avatar-opt').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
}
function finishOnboarding() {
  const name = document.getElementById('onboardName').value.trim();
  if (!name) { showToast('⚠️ لازم تكتب اسمك الأول'); return; }
  const avatarBtn = document.querySelector('#onboardEmojiRow .avatar-opt.selected');
  const profile = { name, gender: onboardGender, avatarUrl: avatarBtn ? avatarBtn.dataset.avatarUrl : dicebearUrl(AVATAR_KEYS[onboardGender][0]) };
  localStorage.setItem('drmonic_user_profile', JSON.stringify(profile));
  document.getElementById('onboardModal').classList.remove('open');
  applyPersonalization();
  showWelcomeSplash(profile);
}
function applyPersonalization() {
  const p = getUserProfile();
  if (!p) return;
  const genderSymbol = p.gender === 'female' ? '♀' : '♂';
  const vocative = `يا ${p.name}`;
  if (aiAssistantMessages.length <= 1) {
    const verb = p.gender === 'female' ? 'افتحي' : 'افتح';
    aiAssistantMessages = [{ role: 'assistant', text: `أهلاً ${vocative} ${genderSymbol}! ${verb} أي حالة أو ECG أو X-Ray واسألني عنها، أو اختار زر سريع من تحت.` }];
  }
  const logo = document.querySelector('.logo-text');
  if (logo) {
    let tag = document.getElementById('userWelcomeTag');
    if (!tag) {
      tag = document.createElement('span');
      tag.id = 'userWelcomeTag';
      tag.style.cssText = 'font-size:0.7rem;color:var(--text2);display:flex;align-items:center;gap:4px;font-weight:600;';
      logo.appendChild(tag);
    }
    tag.innerHTML = `<img src="${p.avatarUrl}" alt="" width="16" height="16" style="border-radius:50%;object-fit:cover;object-position:top center;" /> أهلاً ${p.name} ${genderSymbol}`;
  }
}

/* ══════════════════════════════════════════════════════════════
   ⚙️ Profile settings (change name / avatar later from Settings)
   ══════════════════════════════════════════════════════════════ */
let profileSettingsGender = 'male';
function renderProfileSettingsSection() {
  const p = getUserProfile() || { name: '', gender: 'male', avatarUrl: dicebearUrl(AVATAR_KEYS.male[0]) };
  const nameEl = document.getElementById('profileSettingsName');
  if (nameEl) nameEl.value = p.name || '';
  profileSettingsGender = p.gender === 'female' ? 'female' : 'male';
  profileSettingsRenderAvatarRow(p.avatarUrl);
}
function profileSettingsSetGender(g) {
  profileSettingsGender = g;
  profileSettingsRenderAvatarRow();
}
function profileSettingsRenderAvatarRow(selectedUrl) {
  document.getElementById('profileSettingsMaleBtn').classList.toggle('btn-primary', profileSettingsGender === 'male');
  document.getElementById('profileSettingsFemaleBtn').classList.toggle('btn-primary', profileSettingsGender === 'female');
  const row = document.getElementById('profileSettingsEmojiRow');
  const keys = AVATAR_KEYS[profileSettingsGender];
  row.innerHTML = keys.map((key, i) => {
    const url = dicebearUrl(key);
    const selected = selectedUrl ? url === selectedUrl : i === 0;
    return `<button type="button" class="avatar-opt${selected ? ' selected' : ''}" data-avatar-url="${url}" onclick="profileSettingsPickAvatar(this)">
      <img src="${url}" alt="avatar" width="64" height="64" /></button>`;
  }).join('');
}
function profileSettingsPickAvatar(btn) {
  btn.parentElement.querySelectorAll('.avatar-opt').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
}
function showWelcomeSplash(p) {
  if (!p) return;
  const genderSymbol = p.gender === 'female' ? '♀' : '♂';
  const hour = new Date().getHours();
  const isNight = hour < 5 || hour >= 22;
  const nightWord = p.gender === 'female' ? 'سهرانة' : 'سهران';
  const greeting = isNight ? `${nightWord} معنا؟ 🌙` : hour < 12 ? '☀️ صباح الخير' : hour < 17 ? 'نهارك سعيد ☀️' : '🌆 مساء الخير';
  const el = document.createElement('div');
  el.id = 'welcomeSplash';
  el.innerHTML = `
    <div class="welcome-splash-card">
      <img class="welcome-splash-avatar" src="${p.avatarUrl}" alt="" />
      <div class="welcome-splash-text">أهلاً ${p.name} ${genderSymbol}</div>
      <div class="welcome-splash-sub">${greeting} — ${p.gender === 'female' ? 'جاهزة تبدئي؟' : 'جاهز تبدأ؟'}</div>
    </div>`;
  el.addEventListener('click', () => closeWelcomeSplash(el));
  document.body.appendChild(el);
  requestAnimationFrame(() => el.classList.add('open'));
  setTimeout(() => closeWelcomeSplash(el), 1600);
}
function closeWelcomeSplash(el) {
  if (!el || !el.parentElement) return;
  el.classList.add('closing');
  el.classList.remove('open');
  setTimeout(() => el.remove(), 400);
}
function saveProfileSettings() {
  const name = document.getElementById('profileSettingsName').value.trim();
  if (!name) { showToast('⚠️ لازم تكتب اسمك الأول'); return; }
  const avatarBtn = document.querySelector('#profileSettingsEmojiRow .avatar-opt.selected');
  const avatarUrl = avatarBtn ? avatarBtn.dataset.avatarUrl : dicebearUrl(AVATAR_KEYS[profileSettingsGender][0]);
  const profile = { name, gender: profileSettingsGender, avatarUrl };
  localStorage.setItem('drmonic_user_profile', JSON.stringify(profile));
  applyPersonalization();
  showToast('✅ تم تحديث ملفك الشخصي');
}

/* ══════════════════════════════════════════════════════════════
   🎛️ AI writing criteria (custom instructions, persisted)
   ══════════════════════════════════════════════════════════════ */
function getAiCriteria() {
  const custom = localStorage.getItem('drmonic_ai_criteria') || '';
  const p = getUserProfile();
  const idLine = p ? `اسم المستخدم اللي بتخاطبه: ${p.name} (${p.gender === 'female' ? 'أنثى' : 'ذكر'}) — خاطبه بصيغة تناسب جنسه.` : '';
  return [idLine, custom].filter(Boolean).join('\n');
}
function openAiCriteria() {
  document.getElementById('aiCriteriaText').value = localStorage.getItem('drmonic_ai_criteria') || '';
  document.getElementById('aiCriteriaModal').classList.add('open');
}
function closeAiCriteria() { document.getElementById('aiCriteriaModal').classList.remove('open'); }
function saveAiCriteria() {
  localStorage.setItem('drmonic_ai_criteria', document.getElementById('aiCriteriaText').value.trim());
  showToast('✅ تم حفظ الكرايتيريا');
  closeAiCriteria();
}

/* ══════════════════════════════════════════════════════════════
   ✍️ Write a case from raw notes — AI COMPOSES the full case
   (different from bulk-fill: this generates new structured prose
   from short raw observations, it doesn't just route existing text)
   ══════════════════════════════════════════════════════════════ */
function openWriteCase() {
  document.getElementById('writeCaseModal').classList.add('open');
  setTimeout(() => document.getElementById('writeCaseText')?.focus(), 50);
}
function closeWriteCase() { document.getElementById('writeCaseModal').classList.remove('open'); }

function isDegenerateAiText(s) {
  if (!s || typeof s !== 'string') return false;
  if (s.length > 8000) return true;
  const bangs = (s.match(/!!/g) || []).length;
  if (bangs >= 4) return true;
  const words = s.trim().split(/\s+/);
  if (words.length > 80) {
    const uniq = new Set(words.map(w => w.toLowerCase()));
    if (uniq.size / words.length < 0.25) return true;
  }
  return false;
}

async function applyWriteCase() {
  const raw = document.getElementById('writeCaseText').value.trim();
  const status = document.getElementById('writeCaseStatus');
  const status2 = document.getElementById('writeCaseStatus2');
  const setStatus = (t) => { if (status) status.textContent = t; if (status2) status2.textContent = t; };
  const btn = document.getElementById('writeCaseRunBtn');
  if (!raw) { showToast('⚠️ احكيلنا تفاصيل الحالة أولاً'); return; }
  const apiKey = aiAssistantGetApiKey();
  if (!apiKey) { showToast('⚠️ هاي الميزة محتاجة مفتاح Gemini — ضيفه من صفحة الإعدادات ⚙️ أولاً'); return; }

  btn.disabled = true;
  setStatus('⏳ عم يبني الحالة...');
  const profile = getUserProfile();
  const criteria = getAiCriteria();
  const properties = {};
  Object.keys(SMART_FILL_FIELDS).forEach(k => { properties[k] = { type: 'string' }; });
  properties.mcqs = { type:'array', items:{ type:'object', properties:{ q:{type:'string'}, a:{type:'string'} }, required:['q','a'] } };
  properties.emoji = { type:'string', enum:['👦','👧','👶','🎀','👴','👵','🧑','👩'] };
  const schema = { type: 'object', properties, required: Object.keys(SMART_FILL_FIELDS) };

  const intro = `أنت طبيب مدرّس خبير وكاتب حالات طبية تعليمية بأسلوب قصصي شيّق (نفس أسلوب منصة Dr. Monic التعليمية)، موجّه لطالب طب اسمه ${profile ? profile.name : 'الطالب'}.`;
  const prompt = `${intro}

أسلوب الكتابة (مهم جداً، هذا هو أسلوب منصة Dr. Monic الرسمي — ملتزم فيه حرفياً):
اكتب بأسلوب "ميكس" عربي-انجليزي مريح ودافئ، متل ما دكتور بيشرح لطالب زميله وجهاً لوجه، مش نص أكاديمي رسمي.
- خاطب الطالب مباشرة بالاسم أحياناً (متل "يا ${profile ? profile.name : 'محمد'}")، بأسلوب حماسي ومشجّع، مش جاف ولا رسمي.
- استخدم اللهجة المحكية الفصيحة (بس، يعني، شو، هيك، ليش، عشان، مش) بدل الفصحى الجامدة (لا تقل "إنّ", "لكنّ", "إذ", "بيد أنّ" وأمثالها).
- كل مصطلح طبي أو علمي أو اسم دواء أو اختصار (زي Blood-Ocular Barrier، Autoantigens، Panuveitis، T Cells، KPs...) اكتبه بالإنجليزي بالحرف اللاتيني وسط الجملة العربية مباشرة، بدون ترجمة أو تعريب — هيك هو نفس أسلوب دكتور بيحكي بمزيج عربي-انجليزي طبيعي.
- استخدم علامات تعجب وأسئلة استنكارية/تشويقية بشكل طبيعي (مش مبالغ فيه) لجعل الشرح حيوي ومثير، مش سرد جاف لحقائق.
- اعتبر كل حقل "قصة" مصغّرة: تسلسل أحداث أو تشبيه بسيط قبل الحقائق التقنية، مش قائمة معلومات باردة.
- ممنوع منعاً باتاً الأسلوب الأكاديمي الجاف أو لغة التقارير الرسمية أو الفصحى الصحفية.

هاي ملاحظات من طبيب/طالب عن حالة (ممكن تكون تفصيلية أو مجرد سطر وحدة قصير زي "حالة حادث سير"):

"""${raw}"""

مهمتك: ابنِ حالة تعليمية كاملة واقعية ومنطقية طبياً حول هاد الموضوع، حتى لو المعطيات قليلة جداً — اعتمد على معرفتك الطبية القياسية لأشهر وأكثر عرض/تشخيص شيوعاً يناسب الوصف المعطى (مثلاً "حادث سير" → اختر عرض كلاسيكي شائع بالطوارئ زي blunt abdominal trauma أو head injury إلخ) وابنِ حوله حالة تعليمية غنية بكل التفاصيل الواقعية (عمر، فحص، تاريخ، تحاليل منطقية). ممنوع تترك الحقول فارغة بحجة "المعلومة غير متوفرة" — بالعكس، اخترع تفاصيل سريرية واقعية ومنطقية بنفسك زي ما يسوي مدرّس طب محترف عند تأليف حالة دراسية، طالما هي متسقة طبياً مع بعضها.

مبدأ التأسيس (الأهم من كل شي): اكتب وكأنك تشرح لصاحبك الطالب هاي أول مرة يسمع فيها هالمعلومة بحياته، وهاي المحاضرة الوحيدة اللي قاعد يدرسها من بين محاضرات كثيرة وما معه وقت يرجع لمرجع خارجي — يعني ممنوع تحكي المعلومة "جاهزة" بدون تأسيس. قبل ما تعطي أي حقيقة (Fact)، ابني لها أساس أول: ليش هاد الشي أصلاً منطقي فسيولوجياً/تشريحياً؟ شو العلاقة السببية خطوة-خطوة؟ اربط كل معلومة بالمعلومة يلي قبلها بسلسلة سببية واضحة (A بيصير B لأنه C، وبالتالي D)، مش قفزة مباشرة للنتيجة.

هيكلة الحقول الطويلة والتحليلية تحديداً (bigpicture, patho, diffdx, mistake, management): هاي الحقول لازم تكون **مفصّلة وطويلة نسبياً** (مو فقرة قصيرة سطرين)، ومنظّمة هيك بالضبط:
- إذا في أكثر من احتمال/تشخيص/خطوة، رقّمها (1. 2. 3.) مع عنوان فرعي **Bold** لكل نقطة (اسم الاحتمال/المفهوم بالعربي والإنجليزي).
- تحت كل رقم، فصّل بنقاط فرعية (تبدأ بـ *) تشرح: ليش هالاحتمال منطقي؟ شو الرابط السببي مع معطيات الحالة (تاريخ، عمر، عرض)؟ ولو في نتيجة فحص أو تحليل "سلبية/Negative"، لازم تفسّر صراحة ليش هي سلبية رغم وجود المرض (زي "ليش السماعة نظيفة رغم PE؟ لأن..." — هذا بالضبط النوع من الشرح المطلوب).
- بين كل نقطة رئيسية والتانية، اترك سطر فاضي (فقرة منفصلة) — ما تكدس كل شي بفقرة وحدة متلاصقة.
- بالنسبة لأي مصطلح تقني إنجليزي مهم، حطه بالإنجليزي جنب الشرح العربي (زي ما بأسلوب الكتابة فوق).

وزّع المحتوى على حقول الـ JSON التالية:
- startMsg: ترحيب قصير وتشويقي بالحالة (سطر أو سطرين)
- name, age, complaint, diagnosis
- bigpicture: تأسيس شامل لفكرة الحالة من الصفر — ليش هاي الحالة مهمة، شو المفهوم الأساسي يلي لازم تفهمه قبل أي شي (فقرتين إلى ثلاث، بنفس هيكلة التأسيس فوق لو المفهوم فيه أكثر من طبقة)
- scenario: سرد قصصي لتطور الحالة (فقرة أو فقرتين)
- patho: الفيزيولوجيا المرضية بالتفصيل الكامل — سلسلة سببية كاملة خطوة بخطوة من السبب الجذري للنتيجة النهائية، بنفس هيكلة الترقيم والتأسيس فوق (مو فقرة وحدة مختصرة — هذا أهم حقل بالحالة ولازم يكون الأغنى)
- diffdx: كل تشخيص تفريقي محتمل (2-4) مرقّم مع عنوان Bold، وتحته نقاط فرعية تشرح ليش هو احتمال وارد وليش نتائج الفحص المعطاة (سلبية أو إيجابية) تتوافق أو تستبعده — بالضبط بأسلوب "ليش X سلبي رغم كذا؟"
- mistake: خطأ شائع يقع فيه الطلاب، مع تفسير ليش الطلاب يقعوا فيه وليش هو غلط (فقرة، مو نقطة سطر وحدة)
- management: خطوات العلاج مرقّمة بالترتيب المنطقي، كل خطوة مع سبب ليش هي بهاد الترتيب
- history: أهم أسئلة التاريخ المرضي (نقاط)
- exam: أهم علامات الفحص السريري (نقاط)
- labs: أهم نتائج التحاليل/الأشعة المتوقعة (نقاط)
- dontmiss: نقطة أو نقطتين لازم ما تفوت الطالب
- tricks: تريك تشخيصي سريع واحد أو اثنين، مختصرين وواضحين (بدون تكرار أو حشو إطلاقاً)
- recap: ملخص سريع للنقاط الرئيسية (نقاط)
- endMsg: رسالة ختامية قصيرة
- notes: أي ملاحظة إضافية مفيدة (اختياري، سطر أو سطرين، أو فاضي لو ما في داعي)
- mcqs: 2-3 أسئلة MCQ تعليمية مرتبطة بالحالة مع الجواب
- emoji: الأفاتار الأنسب حسب جنس/عمر المريض

قواعد صارمة وحاسمة: هذا محتوى طبي تعليمي بحت موجّه لطالب طب — تعامل مع أي موضوع طبي (بما فيه الأمراض المنقولة جنسياً، الإدمان، الصحة النفسية، الإصابات، إلخ) بمهنية طبية عادية تماماً بدون أي تحفظ أو تجنب.
ممنوع تماماً ترجع أي حقل فاضي "" أو بجملة عامة سطحية أو نص placeholder ("...", "شرح كذا وكذا"، إلخ) — **كل حقل لازم يتعبى بمحتوى حقيقي ومفصّل وغني**، وتحديداً bigpicture وpatho وdiffdx وmistake وmanagement لازم تكون **طويلة ومؤسَّسة ومرقّمة بعناوين Bold** بالضبط زي ما انشرح فوق (مو فقرة قصيرة مختصرة أبداً لهاي الحقول تحديداً)، بنفس مستوى الغنى والتفصيل اللي تشوفه بحالات Dr.Monic الاحترافية. لو معلومة معينة (متلا نتائج مخبرية) مش أساسية لتشخيص الحالة، اكتب اللي هو منطقي ومتوقع سريرياً بدل ما تتركها فاضية — لا يوجد حقل "غير قابل للتعبئة" إطلاقاً بحالة تعليمية مبنية على تشخيص واضح. كل حقل نصي لازم يكون طبيعي وحيوي بنفس أسلوب الميكس العربي-انجليزي الموصوف فوق، بدون أي تكرار ممل لنفس الكلمة أو نفس التعبير، وبدون أي كلام عن الـ JSON أو الـ schema نفسه. ممنوع رموز LaTeX رياضية (اكتب Unicode مباشرة زي K⁺ و →). ${criteria ? `التزم حرفياً كمان بهاي التعليمات الإضافية من المستخدم فوق أسلوب الميكس: "${criteria}"` : ''}
رجّع JSON فقط مطابق للـ schema بدون أي شرح خارجه.`;

  try {
    const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${AI_ASSISTANT_MODEL}:generateContent?key=${encodeURIComponent(apiKey)}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { responseMimeType: 'application/json', responseSchema: schema, temperature: 0.7, maxOutputTokens: 24576 },
        safetySettings: AI_MEDICAL_SAFETY_SETTINGS
      })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data?.error?.message || ('HTTP ' + res.status));
    const text = data?.candidates?.[0]?.content?.parts?.[0]?.text;
    const parsed = text ? JSON.parse(text) : null;
    if (!parsed) throw new Error('empty response');

    let filledCount = 0, skippedCount = 0;
    Object.entries(SMART_FILL_FIELDS).forEach(([key, def]) => {
      const val = parsed[key];
      if (!val) return;
      if (isDegenerateAiText(val)) { skippedCount++; return; }
      const cleaned = cleanScientificText(val);
      const el = document.getElementById(def.el);
      if (!el) return;
      if (def.kind === 'select') {
        const specs = allSpecialties();
        const match = specs.find(s => s.includes(cleaned) || cleaned.includes(s));
        if (match) el.value = match;
        else { if (!settings.customSpecialties.includes(cleaned)) { settings.customSpecialties.push(cleaned); localStorage.setItem('drmonic_settings', JSON.stringify(settings)); } renderSpecialtyControls(); el.value = cleaned; }
      } else { el.value = cleaned; }
      filledCount++;
    });
    if (Array.isArray(parsed.mcqs)) parsed.mcqs.forEach(mcq => { if (mcq.q && !isDegenerateAiText(mcq.q)) addMCQ(cleanScientificText(mcq.q), cleanScientificText(mcq.a || '')); });
    let emoji = parsed.emoji || heuristicGuessEmoji(raw);
    if (emoji) { const opt = document.querySelector(`.emoji-opt[data-emoji="${emoji}"]`); if (opt) selectEmoji(opt); }

    setStatus(skippedCount ? `✅ تعبّت ${filledCount} حقل (تجاهلنا ${skippedCount} رد غير منطقي — راجعهم يدوياً)` : `✅ تمت كتابة الحالة (${filledCount} حقل) — راجعها قبل الحفظ`);
    showToast('✅ الحالة اتكتبت وانعبت بالخانات');
    closeWriteCase();
  } catch (err) {
    console.warn('Write-case failed:', err);
    setStatus('❌ صار خطأ، جرب كمان مرة');
    showToast('⚠️ ما قدرنا نكتب الحالة — تأكد من مفتاح Gemini');
  }
  btn.disabled = false;
}

